$TestFile = "$env:USERPROFILE\rexuser-transfer-v3.txt"
if (-not (Test-Path -LiteralPath $TestFile)) {
  Set-Content -LiteralPath $TestFile -Value "Harmless rexuser transfer practice." -Encoding ascii
}
